import java.io.Serializable;

public class TaskEvent implements Serializable {

    public static final int EVENT_SUBMIT = 0;

    private long timestampMicros;
    private long jobId;
    private long taskIndex;
    private int eventType;

    public TaskEvent() {}

    public TaskEvent(long timestampMicros, long jobId, long taskIndex, int eventType) {
        this.timestampMicros = timestampMicros;
        this.jobId = jobId;
        this.taskIndex = taskIndex;
        this.eventType = eventType;
    }

    public long getTimestampMicros() {
        return timestampMicros;
    }

    public void setTimestampMicros(long timestampMicros) {
        this.timestampMicros = timestampMicros;
    }

    public long getTimestampMillis() {
        return timestampMicros / 1000L;
    }

    public long getJobId() {
        return jobId;
    }

    public void setJobId(long jobId) {
        this.jobId = jobId;
    }

    public long getTaskIndex() {
        return taskIndex;
    }

    public void setTaskIndex(long taskIndex) {
        this.taskIndex = taskIndex;
    }

    public int getEventType() {
        return eventType;
    }

    public void setEventType(int eventType) {
        this.eventType = eventType;
    }

    public boolean isSubmit() {
        return eventType == EVENT_SUBMIT;
    }

    public static TaskEvent fromCsvLine(String line) {
        // Task events schema (v2.1):
        // 0 timestamp (micros), 1 missing info, 2 job id, 3 task index, 4 machine id,
        // 5 event type, ...
        String[] f = line.split(",", -1);
        long ts = Long.parseLong(f[0]);
        long jobId = Long.parseLong(f[2]);
        long taskIndex = Long.parseLong(f[3]);
        int eventType = Integer.parseInt(f[5]);
        return new TaskEvent(ts, jobId, taskIndex, eventType);
    }
}
