", "new_str": "package clusterdata.query;

import clusterdata.datatypes.JobEvent;
import clusterdata.datatypes.TaskEvent;
import clusterdata.utils.AppBase;
import clusterdata.utils.FinalTupleFileSink;
import clusterdata.utils.GzipCsvSource;
import org.apache.flink.api.common.eventtime.WatermarkStrategy;
import org.apache.flink.api.common.functions.AggregateFunction;
import org.apache.flink.api.common.functions.MapFunction;
import org.apache.flink.api.java.tuple.Tuple2;
import org.apache.flink.api.java.utils.ParameterTool;
import org.apache.flink.streaming.api.datastream.DataStream;
import org.apache.flink.streaming.api.datastream.SingleOutputStreamOperator;
import org.apache.flink.streaming.api.environment.StreamExecutionEnvironment;
import org.apache.flink.streaming.api.functions.windowing.ProcessWindowFunction;
import org.apache.flink.streaming.api.windowing.assigners.EventTimeSessionWindows;
import org.apache.flink.streaming.api.windowing.time.Time;
import org.apache.flink.streaming.api.windowing.windows.TimeWindow;
import org.apache.flink.util.Collector;

import java.io.BufferedReader;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.HashSet;
import java.util.Set;
import java.util.zip.GZIPInputStream;

public class LongestSessionPerJob extends AppBase {

    public static void main(String[] args) throws Exception {

        ParameterTool params = ParameterTool.fromArgs(args);
        String taskInput = params.get("task_input", null);
        String jobInput = params.get("job_input", null);
        String outputPath = params.get("output", null);
        final int sesssize = params.getInt("sesssize", 600);

        if (taskInput == null || jobInput == null || outputPath == null) {
            throw new IllegalArgumentException("Required parameters: task_input, job_input, output");
        }

        final Set<Long> finishedJobs = readFinishedJobs(jobInput);

        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
        env.setParallelism(1);

        DataStream<TaskEvent> tasks = env.addSource(
                taskSourceOrTest(new GzipCsvSource<>(taskInput, TaskEvent::fromCsvLine))
        );

        WatermarkStrategy<TaskEvent> taskWm = WatermarkStrategy
                .<TaskEvent>forMonotonousTimestamps()
                .withTimestampAssigner((e, ts) -> e.getTimestampMillis());

        SingleOutputStreamOperator<TaskEvent> submitTasks = tasks
                .assignTimestampsAndWatermarks(taskWm)
                .filter(TaskEvent::isSubmit);

        SingleOutputStreamOperator<Tuple2<Long, Long>> stageCounts = submitTasks
                .keyBy(TaskEvent::getJobId)
                .window(EventTimeSessionWindows.withGap(Time.seconds(sesssize)))
                .aggregate(new CountAgg(), new SessionCountResult());

        // only consider jobs that have terminated (FINISH/KILL/FAIL/LOST)
        SingleOutputStreamOperator<Tuple2<Long, Long>> filteredStageCounts = stageCounts
                .filter(t -> finishedJobs.contains(t.f0));

        DataStream<Tuple2<Long, Long>> finishedJobZeros = env
                .fromCollection(finishedJobs)
                .map((MapFunction<Long, Tuple2<Long, Long>>) id -> Tuple2.of(id, 0L));

        DataStream<Tuple2<Long, Long>> candidates = finishedJobZeros.union(filteredStageCounts);

        candidates
                .addSink(sinkOrTest(new FinalTupleFileSink(outputPath)))
                .setParallelism(1);

        env.execute("LongestSessionPerJob");
    }

    private static final class CountAgg implements AggregateFunction<TaskEvent, Long, Long> {
        @Override
        public Long createAccumulator() {
            return 0L;
        }

        @Override
        public Long add(TaskEvent value, Long accumulator) {
            return accumulator + 1L;
        }

        @Override
        public Long getResult(Long accumulator) {
            return accumulator;
        }

        @Override
        public Long merge(Long a, Long b) {
            return a + b;
        }
    }

    private static final class SessionCountResult extends ProcessWindowFunction<Long, Tuple2<Long, Long>, Long, TimeWindow> {
        @Override
        public void process(Long key, Context context, Iterable<Long> elements, Collector<Tuple2<Long, Long>> out) {
            long cnt = elements.iterator().next();
            out.collect(Tuple2.of(key, cnt));
        }
    }

    private static Set<Long> readFinishedJobs(String jobInput) throws Exception {
        Set<Long> finished = new HashSet<>();
        Path p = Paths.get(stripFileScheme(jobInput));
        try (InputStream is = Files.newInputStream(p);
             InputStream maybeGzip = p.toString().endsWith(".gz") ? new GZIPInputStream(is) : is;
             BufferedReader br = new BufferedReader(new InputStreamReader(maybeGzip, StandardCharsets.UTF_8))) {

            String line;
            while ((line = br.readLine()) != null) {
                line = line.trim();
                if (line.isEmpty()) {
                    continue;
                }
                JobEvent e = JobEvent.fromCsvLine(line);
                if (e.isTerminal()) {
                    finished.add(e.getJobId());
                }
            }
        }
        return finished;
    }

    private static String stripFileScheme(String p) {
        if (p == null) {
            return null;
        }
        if (p.startsWith("file://")) {
            return p.substring("file://".length());
        }
        return p;
    }
}
", "summary": "Implement LongestSessionPerJob Flink pipeline with session stages", "security_risk": "MEDIUM"}

