{"command": "create", "path": "/app/workspace/src/main/java/clusterdata/utils/FinalTupleFileSink.java", "file_text": "package clusterdata.utils;

import org.apache.flink.configuration.Configuration;
import org.apache.flink.streaming.api.functions.sink.RichSinkFunction;
import org.apache.flink.api.java.tuple.Tuple2;

import java.io.BufferedWriter;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.nio.file.StandardOpenOption;
import java.util.HashMap;
import java.util.Map;

public class FinalTupleFileSink extends RichSinkFunction<Tuple2<Long, Long>> {

    private final String outputPath;

    private transient Map<Long, Long> maxByJob;

    public FinalTupleFileSink(String outputPath) {
        this.outputPath = outputPath;
    }

    @Override
    public void open(Configuration parameters) {
        maxByJob = new HashMap<>();
    }

    @Override
    public void invoke(Tuple2<Long, Long> value, Context context) {
        if (value == null) {
            return;
        }
        long jobId = value.f0;
        long cnt = value.f1;
        maxByJob.merge(jobId, cnt, Math::max);
    }

    @Override
    public void close() throws Exception {
        if (getRuntimeContext().getIndexOfThisSubtask() != 0) {
            return;
        }
        Path p = Paths.get(stripFileScheme(outputPath));
        Path parent = p.getParent();
        if (parent != null) {
            Files.createDirectories(parent);
        }

        try (BufferedWriter w = Files.newBufferedWriter(
                p,
                StandardCharsets.UTF_8,
                StandardOpenOption.CREATE,
                StandardOpenOption.TRUNCATE_EXISTING,
                StandardOpenOption.WRITE
        )) {
            for (Map.Entry<Long, Long> e : maxByJob.entrySet()) {
                w.write("(" + e.getKey() + "," + e.getValue() + ")");
                w.newLine();
            }
        }
    }

    private static String stripFileScheme(String p) {
        if (p == null) {
            return null;
        }
        if (p.startsWith("file://")) {
            return p.substring("file://".length());
        }
        return p;
    }
}
