    32	    @Override
    33	    public void run(SourceContext<T> ctx) throws Exception {
    34	        Path p = Paths.get(stripFileScheme(path));
    35	        try (InputStream is = Files.newInputStream(p);
    36	             InputStream maybeGzip = p.toString().endsWith(".gz") ? new GZIPInputStream(is) : is;
    37	             BufferedReader br = new BufferedReader(new InputStreamReader(maybeGzip, StandardCharsets.UTF_8))) {
    38	
    39	            String line;
    40	            while (running && (line = br.readLine()) != null) {
    41	                line = line.trim();
    42	                if (line.isEmpty()) {
    43	                    continue;
    44	                }
    45	                T v = parser.parse(line);
    46	                synchronized (ctx.getCheckpointLock()) {
    47	                    ctx.collect(v);
    48	                }
    49	            }
    50	            synchronized (ctx.getCheckpointLock()) {
