{"command": "create", "path": "/app/workspace/src/main/java/clusterdata/utils/LocalFileSink.java", "file_text": "package clusterdata.utils;

import org.apache.flink.configuration.Configuration;
import org.apache.flink.streaming.api.functions.sink.RichSinkFunction;

import java.io.BufferedWriter;
import java.io.Serializable;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.nio.file.StandardOpenOption;

public class LocalFileSink extends RichSinkFunction<String> implements Serializable {

    private final String outputPath;

    private transient BufferedWriter writer;

    public LocalFileSink(String outputPath) {
        this.outputPath = outputPath;
    }

    @Override
    public void open(Configuration parameters) throws Exception {
        if (getRuntimeContext().getIndexOfThisSubtask() != 0) {
            return;
        }
        Path p = Paths.get(stripFileScheme(outputPath));
        Path parent = p.getParent();
        if (parent != null) {
            Files.createDirectories(parent);
        }
        writer = Files.newBufferedWriter(
                p,
                StandardCharsets.UTF_8,
                StandardOpenOption.CREATE,
                StandardOpenOption.TRUNCATE_EXISTING,
                StandardOpenOption.WRITE
        );
    }

    @Override
    public void invoke(String value, Context context) throws Exception {
        if (writer == null) {
            return;
        }
        writer.write(value);
        writer.newLine();
    }

    @Override
    public void close() throws Exception {
        if (writer != null) {
            writer.flush();
            writer.close();
        }
    }

    private static String stripFileScheme(String p) {
        if (p == null) {
            return null;
        }
        if (p.startsWith("file://")) {
            return p.substring("file://".length());
        }
        return p;
    }
}
