public class FinalTupleFileSink extends RichSinkFunction<Tuple2<Long, Long>> {

    private final String outputPath;

    private transient Map<Long, Long> maxByJob;
    private transient Set<Long> finishedJobs;

    public FinalTupleFileSink(String outputPath) {
        this.outputPath = outputPath;
    }

    @Override
    public void open(Configuration parameters) {
        maxByJob = new HashMap<>();
        finishedJobs = new HashSet<>();
    }

    @Override
    public void invoke(Tuple2<Long, Long> value, Context context) {
        if (value == null) {
            return;
        }
        long jobId = value.f0;
        long v = value.f1;

        // Convention:
        // - v < 0  => job terminated marker
        // - v >= 0 => stage size candidate
        if (v < 0) {
            finishedJobs.add(jobId);
            return;
        }

        maxByJob.merge(jobId, v, Math::max);
    }

    @Override
    public void close() throws Exception {
        if (getRuntimeContext().getIndexOfThisSubtask() != 0) {
            return;
        }
        Path p = Paths.get(stripFileScheme(outputPath));
        Path parent = p.getParent();
        if (parent != null) {
            Files.createDirectories(parent);
        }

        try (BufferedWriter w = Files.newBufferedWriter(
