    16	public class GzipCsvSource<T> implements SourceFunction<T> {
    17	
    18	    public interface LineParser<T> extends Serializable {
    19	        T parse(String line);
    20	    }
    21	
    22	    private final String path;
    23	    private final LineParser<T> parser;
    24	
    25	    private volatile boolean running = true;
    26	
    27	    public GzipCsvSource(String path, LineParser<T> parser) {
    28	        this.path = path;
    29	        this.parser = parser;
    30	    }
    31	
    32	    @Override
    33	    public void run(SourceContext<T> ctx) throws Exception {
    34	        Path p = Paths.get(stripFileScheme(path));
    35	        try (InputStream is = Files.newInputStream(p);
    36	             InputStream maybeGzip = p.toString().endsWith(".gz") ? new GZIPInputStream(is) : is;
    37	             BufferedReader br = new BufferedReader(new InputStreamReader(maybeGzip, StandardCharsets.UTF_8))) {
    38	
    39	            String line;
    40	            while (running && (line = br.readLine()) != null) {
    41	                line = line.trim();
    42	                if (line.isEmpty()) {
    43	                    continue;
    44	                }
    45	                T v = parser.parse(line);
    46	                synchronized (ctx.getCheckpointLock()) {
    47	                    ctx.collect(v);
    48	                }
    49	            }
    50	            synchronized (ctx.getCheckpointLock()) {
    51	                ctx.emitWatermark(Watermark.MAX_WATERMARK);
    52	            }
    53	        }
    54	    }
    55	
    56	    @Override
    57	    public void cancel() {
    58	        running = false;
    59	    }
