{"command": "create", "path": "/app/workspace/src/main/java/clusterdata/utils/GzipCsvSource.java", "file_text": "package clusterdata.utils;

import org.apache.flink.streaming.api.functions.source.SourceFunction;

import java.io.BufferedReader;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Serializable;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.zip.GZIPInputStream;

public class GzipCsvSource<T> implements SourceFunction<T> {

    public interface LineParser<T> extends Serializable {
        T parse(String line);
    }

    private final String path;
    private final LineParser<T> parser;

    private volatile boolean running = true;

    public GzipCsvSource(String path, LineParser<T> parser) {
        this.path = path;
        this.parser = parser;
    }

    @Override
    public void run(SourceContext<T> ctx) throws Exception {
        Path p = Paths.get(stripFileScheme(path));
        try (InputStream is = Files.newInputStream(p);
             InputStream maybeGzip = p.toString().endsWith(".gz") ? new GZIPInputStream(is) : is;
             BufferedReader br = new BufferedReader(new InputStreamReader(maybeGzip, StandardCharsets.UTF_8))) {

            String line;
            while (running && (line = br.readLine()) != null) {
                line = line.trim();
                if (line.isEmpty()) {
                    continue;
                }
                T v = parser.parse(line);
                synchronized (ctx.getCheckpointLock()) {
                    ctx.collect(v);
                }
            }
        }
    }

    @Override
    public void cancel() {
        running = false;
    }

    private static String stripFileScheme(String p) {
        if (p == null) {
            return null;
        }
        if (p.startsWith("file://")) {
            return p.substring("file://".length());
        }
        return p;
    }
}
", "summary": "Create gzipped CSV SourceFunction utility", "security_risk": "MEDIUM"}

{"command": "create", "path": "/app/workspace/src/main/java/clusterdata/utils/LocalFileSink.java", "file_text": "package clusterdata.utils;

import org.apache.flink.configuration.Configuration;
import org.apache.flink.streaming.api.functions.sink.RichSinkFunction;

import java.io.BufferedWriter;
import java.io.Serializable;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.nio.file.StandardOpenOption;

public class LocalFileSink extends RichSinkFunction<String> implements Serializable {

    private final String outputPath;

    private transient BufferedWriter writer;

    public LocalFileSink(String outputPath) {
        this.outputPath = outputPath;
    }

    @Override
    public void open(Configuration parameters) throws Exception {
        if (getRuntimeContext().getIndexOfThisSubtask() != 0) {
            return;
        }
        Path p = Paths.get(stripFileScheme(outputPath));
        Path parent = p.getParent();
        if (parent != null) {
            Files.createDirectories(parent);
        }
        writer = Files.newBufferedWriter(
                p,
                StandardCharsets.UTF_8,
                StandardOpenOption.CREATE,
                StandardOpenOption.TRUNCATE_EXISTING,
                StandardOpenOption.WRITE
        );
    }

    @Override
    public void invoke(String value, Context context) throws Exception {
        if (writer == null) {
            return;
        }
        writer.write(value);
        writer.newLine();
    }

    @Override
    public void close() throws Exception {
        if (writer != null) {
            writer.flush();
            writer.close();
        }
    }

    private static String stripFileScheme(String p) {
        if (p == null) {
            return null;
        }
        if (p.startsWith("file://")) {
            return p.substring("file://".length());
        }
        return p;
    }
}
