    18	public class FinalTupleFileSink extends RichSinkFunction<Tuple2<Long, Long>> {
    19	
    20	    private final String outputPath;
    21	
    22	    private transient Map<Long, Long> maxByJob;
    23	    private transient Set<Long> finishedJobs;
    24	
    25	    public FinalTupleFileSink(String outputPath) {
    26	        this.outputPath = outputPath;
    27	    }
    28	
    29	    @Override
    30	    public void open(Configuration parameters) {
    31	        maxByJob = new HashMap<>();
    32	        finishedJobs = new HashSet<>();
    33	    }
    34	
    35	    @Override
    36	    public void invoke(Tuple2<Long, Long> value, Context context) {
    37	        if (value == null) {
    38	            return;
    39	        }
    40	        long jobId = value.f0;
    41	        long v = value.f1;
    42	
    43	        // Convention:
    44	        // - v < 0  => job terminated marker
    45	        // - v >= 0 => stage size candidate
    46	        if (v < 0) {
    47	            finishedJobs.add(jobId);
    48	            return;
    49	        }
    50	
    51	        maxByJob.merge(jobId, v, Math::max);
    52	    }
    53	
    54	    @Override
    55	    public void close() throws Exception {
    56	        if (getRuntimeContext().getIndexOfThisSubtask() != 0) {
    57	            return;
    58	        }
    59	        Path p = Paths.get(stripFileScheme(outputPath));
    60	        Path parent = p.getParent();
    61	        if (parent != null) {
    62	            Files.createDirectories(parent);
    63	        }
    64	
    65	        try (BufferedWriter w = Files.newBufferedWriter(
    66	                p,
    67	                StandardCharsets.UTF_8,
    68	                StandardOpenOption.CREATE,
    69	                StandardOpenOption.TRUNCATE_EXISTING,
    70	                StandardOpenOption.WRITE
    71	        )) {
    72	            for (Long jobId : finishedJobs) {
    73	                long maxStage = maxByJob.getOrDefault(jobId, 0L);
    74	                w.write("(" + jobId + "," + maxStage + ")");
    75	                w.newLine();
    76	            }
    77	        }
    78	    }
