{"command": "create", "path": "/app/workspace/src/main/java/clusterdata/utils/GzipCsvSource.java", "file_text": "package clusterdata.utils;

import org.apache.flink.streaming.api.functions.source.SourceFunction;

import java.io.BufferedReader;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Serializable;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.zip.GZIPInputStream;

public class GzipCsvSource<T> implements SourceFunction<T> {

    public interface LineParser<T> extends Serializable {
        T parse(String line);
    }

    private final String path;
    private final LineParser<T> parser;

    private volatile boolean running = true;

    public GzipCsvSource(String path, LineParser<T> parser) {
        this.path = path;
        this.parser = parser;
    }

    @Override
    public void run(SourceContext<T> ctx) throws Exception {
        Path p = Paths.get(stripFileScheme(path));
        try (InputStream is = Files.newInputStream(p);
             InputStream maybeGzip = p.toString().endsWith(".gz") ? new GZIPInputStream(is) : is;
             BufferedReader br = new BufferedReader(new InputStreamReader(maybeGzip, StandardCharsets.UTF_8))) {

            String line;
            while (running && (line = br.readLine()) != null) {
                line = line.trim();
                if (line.isEmpty()) {
                    continue;
                }
                T v = parser.parse(line);
                synchronized (ctx.getCheckpointLock()) {
                    ctx.collect(v);
                }
            }
        }
    }

    @Override
    public void cancel() {
        running = false;
    }

    private static String stripFileScheme(String p) {
        if (p == null) {
            return null;
        }
        if (p.startsWith("file://")) {
            return p.substring("file://".length());
        }
        return p;
    }
}
", "summary": "Create gzipped CSV SourceFunction utility", "security_risk": "MEDIUM"}

