        this.jobId = jobId;
        this.eventType = eventType;
    }

    public long getTimestampMicros() {
        return timestampMicros;
    }

    public void setTimestampMicros(long timestampMicros) {
        this.timestampMicros = timestampMicros;
    }

    public long getTimestampMillis() {
        return timestampMicros / 1000L;
    }

    public long getJobId() {
        return jobId;
    }

    public void setJobId(long jobId) {
        this.jobId = jobId;
    }

    public int getEventType() {
        return eventType;
    }

    public void setEventType(int eventType) {
        this.eventType = eventType;
    }

    public boolean isTerminal() {
        // From the clusterdata schema: FAIL(3), FINISH(4), KILL(5), LOST(6)
        return eventType == 3 || eventType == 4 || eventType == 5 || eventType == 6;
    }

    public static JobEvent fromCsvLine(String line) {
        // Job events schema (v2.1):
        // 0 timestamp (micros), 1 missing info, 2 job id, 3 event type, ...
        String[] f = line.split(",", -1);
        long ts = Long.parseLong(f[0]);
        long jobId = Long.parseLong(f[2]);
        int eventType = Integer.parseInt(f[3]);
        return new JobEvent(ts, jobId, eventType);
    }
}
